  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "The satellite must provide images for a fluid lensing tool to analyse reefs beneath the water surface."
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required."
        },
        {
          "where": "Introduction",
          "quote": "The proposed satellite would likely be used by governmental and science agencies (e.g. CSIRO, BOM) for research and/or education."
        },
        {
          "where": "Executive Summary",
          "quote": "The satellite, nicknamed ZYZZsat (Z-axis/Y-axis Zeroed Zoning Satellite), is operated and accessed from Australia ground facilities"
        }
      ],
      "reasoning": "The mission purpose and need are explained with useful environmental context and sources, and the report gives a reason for using one spacecraft. Likely users are identified, but the mission operator and customer roles are not clearly distinguished, and the concept's operational rationale remains somewhat general."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "Specifically, an altitude of 600km requires a mean inclination of $ 97.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "Systems Tool Kit 11 (STK) was used to calculate access periods as seen below:"
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "A span of five years is a sound estimate of the useful lifespan of the proposed satellite."
        }
      ],
      "reasoning": "Most required design topics are addressed, and STK imagery and access outputs provide some evidence. However, key design choices and performance are not adequately supported: payload imaging capability, launch compatibility, communication links, and EOL disposal lifetime are not quantified. The access table also contains a duplicate entry and its summary statistics do not account for all displayed rows."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "The Mt Pleasant Radio Observatory is well-located to receive data from this orbit type constantly and for long durations."
        }
      ],
      "reasoning": "The conclusion recaps the selected launch vehicle, orbit, and ground facility and acknowledges launch uncertainty. It is relevant but mainly summarizes the proposal; it does not critically draw conclusions from the design evidence or qualify unsupported claims about illumination and ground-station performance."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Ground Control & Communications",
          "quote": "DN path for orbits 1-15"
        },
        {
          "where": "Bibliography",
          "quote": "[6] https://en.wikipedia.org/wiki/2021_in_spaceflight. [Online]."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "It acts like a regular sail, utilising a large surface area to ‘ and is suitable for low-earth orbit altitudes [10]."
        }
      ],
      "reasoning": "The report has a clear overall structure, executive summary, and a logical progression through design sections. Presentation is weakened by grammar and incomplete wording, inconsistently numbered or titled figures and tables, and bare or mismatched references. Wikipedia is used as a source despite the assignment's restriction."
    }
  ],
